import pathlib,base64,json,hashlib,os
root=pathlib.Path(__file__).parent
source=pathlib.Path('apps/ocean-life-mother/fish-mother/yellowfin-source-copy-r001/source-workspace/source/tuna_fish_4k.glb')
data=source.read_bytes();runtime=(root/'bundle.js').read_text();out=pathlib.Path('dist/fish-mother-yellowfin');out.mkdir(parents=True,exist_ok=True)
