(out/'BUILD_MANIFEST.json').write_text(json.dumps(manifest,indent=2));(out/'SOURCE_IDENTITY_PROOF.json').write_bytes(pathlib.Path('SOURCE_IDENTITY_PROOF.json').read_bytes());print('BUILD',json.dumps(manifest),flush=True)
